add("tagline_core", "Grow Smarter. Farm Better.", "తెలివిగా పండించండి. మెరుగ్గా జీవించండి.", "புத்திசாலித்தனமாக பயிரிடுங்கள். சிறப்பாக வாழுங்கள்.", "स्मार्ट खेती। बेहतर पैदावार।");
add("tagline_secondary", "Your farm, powered by intelligent technology.", "మీ వ్యవసాయం, మేధో సాంకేతిక పరిజ్ఞానంతో.", "உங்கள் விவசாயம், நுண்ணறிவுத் தொழில்நுட்பத்துடன்.", "आपकी खेती, आधुनिक तकनीक के साथ।");
add("hero_headline", "Grow Smarter. Farm Better.", "తెలివిగా పండించండి. మెరుగ్గా జీవించండి.", "புத்திசாலித்தனமாக பயிரிடுங்கள். சிறப்பாக வாழுங்கள்.", "स्मार्ट खेती। बेहतर पैदावार।");
add("hero_subheadline", 
  "Discover a smarter way to farm with crop insights, soil intelligence, weather guidance and AI-powered farming tools — all in one place.",
  "పంట సలహాలు, నేల ఆరోగ్యం, వాతావరణ సమాచారం మరియు AI ఆధారిత వ్యవసాయ సాధనాలతో స్మార్ట్ సాగు పద్ధతులను ఒకే వేదికపై పొందండి.",
  "பயிர் நுண்ணறிவு, மண் வளம், வானிலை வழிகாட்டல் மற்றும் AI தொழில்நுட்பம் மூலம் நவீன விவசாயத்தை ஒரே தளத்தில் பெறுங்கள்.",
  "फसल सलाह, मिट्टी की सेहत, मौसम पूर्वानुमान और एआई तकनीकों के साथ खेती का आधुनिक तरीका अपनाएं — सब कुछ एक ही मंच पर।"
);
