add("footer_helpline_desc", "Toll-free agricultural support across Indian states.", "భారతీయ రాష్ట్రాల్లో టోల్-ఫ్రీ వ్యవసాయ సహాయం.", "இந்திய மாநிலங்களுக்கான கட்டணமில்லா உதவி.", "भारतीय राज्यों में निःशुल्क कृषि परामर्श एवं सहायता।");

add("disclaimer_heading", "Current Prototype Status & Ethical Disclaimer", "ప్రస్తుత ప్రోటోటైప్ స్థితి & నైతిక నిరాకరణ", "மாதிரி நிலை & பொறுப்புத் துறப்பு", "प्रोटोटाइप स्थिति एवं वैधानिक अस्वीकरण");
add("disclaimer_p1", "This deployment represents Version 1.0 — an interactive functional prototype designed for demonstration, validation, and educational study.", "ఈ వెబ్‌సైట్ వెర్షన్ 1.0 — పరిశోధన, ధృవీకరణ మరియు విద్యార్థులు, రైతుల అధ్యయనం కోసం రూపొందించబడిన క్రియాత్మక ప్రోటోటైప్.", "இந்த தளம் பதிப்பு 1.0 — மாதிரி செயல்விளக்கம் மற்றும் கல்வி நோக்கத்திற்காக வடிவமைக்கப்பட்ட செயல்பாட்டு வடிவம்.", "यह संस्करण 1.0 एक कार्यात्मक प्रोटोटाइप है जो प्रदर्शन, सत्यापन और अध्ययन के लिए बनाया गया है।");
add("disclaimer_li1", "The AI Crop Doctor demonstrates diagnostic visual workflows and symptomatic care protocols; it is not yet connected to a cloud-hosted computer vision neural network.", "AI పంట వైద్యుడు వ్యాధి లక్షణాలను మరియు చికిత్స విధానాలను ప్రదర్శిస్తుంది; ఇది పరిశోధన ఆధారిత నమూనా.", "AI பயிர் மருத்துவர் நோய் அறிகுறிகளையும் தடுப்பு முறைகளையும் விளக்குகிறது; இது மாதிரி ஆய்வு வடிவம்.", "एआई फसल डॉक्टर केवल रोग के लक्षणों और रोकथाम के उपायों का मार्गदर्शन करता है।");
add("disclaimer_li2", "Mandi rates and 5-day weather readings utilize realistic illustrative sample datasets.", "మండి ధరలు మరియు 5 రోజుల వాతావరణ అంచనాలు వాస్తవిక నమూనా డేటా ఆధారంగా లెక్కించబడతాయి.", "மண்டி விலைகள் மற்றும் 5 நாள் வானிலை முன்னறிவிப்பு ஆகியவை மாதிரி தரவுகளை அடிப்படையாகக் கொண்டவை.", "मंडी भाव और 5-दिवसीय मौसम पूर्वानुमान वास्तविक मॉडल डेटा पर आधारित हैं।");
add("disclaimer_li3", "Always verify chemical dosages and disease management decisions with local agricultural extension officers or Krishi Vigyan Kendra (KVK) scientists before spraying.", "రసాయన మందులు పిచికారీ చేసే ముందు ఎల్లప్పుడూ స్థానిక వ్యవసాయ విస్తరణ అధికారులు లేదా కృషి విజ్ఞాన కేంద్రం (KVK) శాస్త్రవేత్తలను సంప్రదించండి.", "மருந்து தெளிப்பதற்கு முன் உள்ளூர் வேளாண் அலுவலர்கள் அல்லது KVK விஞ்ஞானிகளிடம் ஆலோசனை பெறவும்.", "दवा छिड़कने से पहले हमेशा स्थानीय कृषि अधिकारियों या कृषि विज्ञान केंद्र (KVK) के वैज्ञानिकों से सलाह लें।");

// Contact Page Form & Helpline
add("contact_demo_note_title", "Frontend Demonstration Note:", "డెమో ప్రదర్శన గమనిక:", "செயல்விளக்க குறிப்பு:", "प्रदर्शन डेमो सूचना:");
add("contact_demo_note_desc", "This is a frontend demonstration build. Submitting this form displays accessible confirmation feedback, but does not transmit messages to an active email server. For urgent farm queries, please utilize the national Kisan Call Centre.", "ఇది ముందస్తు ప్రదర్శన వెర్షన్. ఈ ఫారమ్‌ను సమర్పించినప్పుడు నిర్ధారణ కనిపిస్తుంది, కానీ ఈమెయిల్ సర్వర్‌కు పంపబడదు. అత్యవసర వ్యవసాయ సలహాల కోసం జాతీయ కిసాన్ కాల్ సెంటర్‌ను సంప్రదించండి.", "இது ஒரு மாதிரி பதிப்பாகும். படிவத்தை சமர்ப்பிக்கும்போது ஒப்புகை மட்டுமே தோன்றும். அவசர விவசாய சந்தேகங்களுக்கு தேசிய விவசாயிகள் அழைப்பு மையத்தை தொடர்பு கொள்ளவும்.", "यह एक डेमो संस्करण है। फॉर्म जमा करने पर केवल पुष्टि दिखाई देगी। तत्काल कृषि परामर्श के लिए कृपया राष्ट्रीय किसान कॉल सेंटर पर संपर्क करें।");
add("contact_name_placeholder", "e.g. Ramesh Patel", "ఉదా: రమేష్ పటేల్", "எ.கா: ரமேஷ் படேல்", "उदा. रमेश पटेल");
