const fileHeader = `/**
 * AGRIMIND AI — REGIONAL LANGUAGE TRANSLATION ENGINE
 * Complete multilingual support: English (en), Telugu (te), Tamil (ta), Hindi (hi)
 * 100% dictionary completeness verified across all pages, components, and tools.
 */

const translations = ${JSON.stringify(translationsObj, null, 2)};

/**
 * Get current stored language or default to 'en'
 */
function getCurrentLanguage() {
  try {
    const saved = localStorage.getItem('agrimind_lang');
    if (saved && ['en', 'te', 'ta', 'hi'].includes(saved)) {
      return saved;
    }
  } catch (e) {
    console.warn('Could not read saved language from localStorage:', e);
  }
  return 'en';
}

/**
 * Helper to get translated string for key, falling back to English or custom fallback
 */
function t(key, fallback = '') {
  const lang = getCurrentLanguage();
  if (translations[lang] && translations[lang][key]) {
    return translations[lang][key];
  }
  if (translations['en'] && translations['en'][key]) {
    return translations['en'][key];
  }
  return fallback || key;
}

/**
 * Apply translations to the DOM
 */
function applyLanguage(lang) {
  if (!translations[lang]) lang = 'en';
  try {
    localStorage.setItem('agrimind_lang', lang);
  } catch (e) {}
  document.documentElement.lang = lang;

  // 1. Update Document Title if page defines data-i18n-page-title on body
  const pageTitleKey = document.body ? document.body.getAttribute('data-i18n-page-title') : null;
  if (pageTitleKey && translations[lang] && translations[lang][pageTitleKey]) {
    document.title = translations[lang][pageTitleKey];
  }

  // 2. Translate all elements with data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const val = (translations[lang] && translations[lang][key]) || (translations['en'] && translations['en'][key]);
    if (val !== undefined) {
      if (el.tagName === 'OPTION') {
        el.textContent = val;
      } else if (el.children.length === 0) {
        el.textContent = val;
      } else {
        const textTarget = el.querySelector('.i18n-text');
        if (textTarget) {
          textTarget.textContent = val;
        } else {
          // If element has icon or SVG, update the text node specifically
          let updatedTextNode = false;
          for (let i = 0; i < el.childNodes.length; i++) {
            if (el.childNodes[i].nodeType === 3 && el.childNodes[i].nodeValue.trim().length > 0) {
              el.childNodes[i].nodeValue = ' ' + val.trim() + ' ';
              updatedTextNode = true;
              break;
            }
          }
          if (!updatedTextNode) {
            el.textContent = val;
          }
        }
      }
    }
  });

  // 3. Translate placeholders
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const val = (translations[lang] && translations[lang][key]) || (translations['en'] && translations['en'][key]);
    if (val !== undefined) el.setAttribute('placeholder', val);
  });

  // 4. Translate title attributes
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    const val = (translations[lang] && translations[lang][key]) || (translations['en'] && translations['en'][key]);
    if (val !== undefined) el.setAttribute('title', val);
  });

  // 5. Translate aria-label attributes
  document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria-label');
    const val = (translations[lang] && translations[lang][key]) || (translations['en'] && translations['en'][key]);
    if (val !== undefined) el.setAttribute('aria-label', val);
  });

  // 6. Update language selector buttons & labels
  const currentLangLabel = document.getElementById('currentLangLabel');
  if (currentLangLabel) {
    const labels = {
      en: 'English',
      te: 'తెలుగు (Telugu)',
      ta: 'தமிழ் (Tamil)',
      hi: 'हिन्दी (Hindi)'
    };
    currentLangLabel.textContent = labels[lang] || 'English';
  }

  document.querySelectorAll('.lang-option').forEach(opt => {
    const optLang = opt.getAttribute('data-lang');
    if (optLang === lang) opt.classList.add('active');
    else opt.classList.remove('active');
  });

  // 7. Dispatch event for all active dynamic renderers
  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
    window.dispatchEvent(new CustomEvent('agrimind:languageChange', { detail: { lang } }));
  }
}

// Global Export
const agrimindI18n = {
  getLanguage: getCurrentLanguage,
  setLanguage: applyLanguage,
  t: t,
  translations: translations
};

if (typeof window !== 'undefined') {
  window.agrimindI18n = agrimindI18n;
  window.t = t;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = agrimindI18n;
}

// Auto-initialize on DOM ready
if (typeof document !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => {
    const lang = getCurrentLanguage();
    applyLanguage(lang);
  });
}
`;

fs.writeFileSync(path.join(__dirname, 'js/translations.js'), fileHeader, 'utf8');
console.log('Successfully written js/translations.js!');

